/**
 * 说说加载器类 - 话题解析增强版
 * 修复：话题标签现在支持点号（.），仅在遇到空格或换行时结束
 */
class MemoLoader {
    constructor(config) {
        this.config = {
            memos: config.memos || "/memos/",
            limit: config.limit || 8,
            domId: config.domId || "#says",
            biliplayer: config.biliplayer || "h5",
            ...config
        };
        this.state = { currentPage: 1, isLoading: false, hasMore: true };
        this.container = null;
        this.saysList = null;
        this.loadButtonContainer = null;
        this.loadButton = null;
        this.init();
    }

    init() {
        this.container = document.querySelector(this.config.domId);
        if (!this.container) throw new Error(`容器 ${this.config.domId} 不存在`);

        this.container.innerHTML = `
            <div id="says-list"></div>
            <div class="says-card bb-container" style="display:none;">
                <button class="bb-load">点击加载更多</button>
            </div>
        `;

        this.saysList = this.container.querySelector("#says-list");
        this.loadButtonContainer = this.container.querySelector(".bb-container");
        this.loadButton = this.container.querySelector(".bb-load");

        this.initMarkedExtensions();
        this.bindEvents();
        this.showLoader();
        this.loadMemos();
    }

    bindEvents() {
        if (this.loadButton) {
            this.loadButton.addEventListener("click", () => {
                if (!this.state.isLoading && this.state.hasMore) {
                    this.loadButton.textContent = "^_^ 努力加载中...";
                    this.loadMemos();
                }
            });
        }
    }

    showLoader() {
        this.saysList.innerHTML = `
            <div class="loader">
                <svg class="circular" viewBox="25 25 50 50">
                    <circle class="path" cx="50" cy="50" r="20" fill="none" stroke-width="2" stroke-miterlimit="10"/>
                </svg>
            </div>`;
    }

    initMarkedExtensions() {
        const renderer = new marked.Renderer();

        // 1. 图片解析
        renderer.image = (token) => {
            const href = token.href || "";
            const text = token.text || "";
            const isEmoji = href.includes("/emoji/");
            return `<img class="img thumbnail-image shadow-lg rounded-lg ${isEmoji ? 'loaded emoji' : ''}" src="${href}" title="${text}" alt="${text}"/>`;
        };

        // 2. 链接解析
        renderer.link = (token) => {
            const href = token.href || "";
            const text = String(token.text || "");
            const isDirectLink = (text === href || text === href.replace(/^https?:\/\//, ''));

            if (isDirectLink) {
                if (href.includes("music.163.com") && href.includes("id=")) {
                    const musicId = href.match(/id=([0-9]+)/);
                    if (musicId && musicId[1]) {
                        return `<div class='w-full' title="${text}"><iframe src="https://music.163.com/outchain/player?type=2&id=${musicId[1]}&auto=0&height=32" frameborder="no" border="0" width="100%" height="52" referrerpolicy="no-referrer"></iframe></div>`;
                    }
                }
                if (href.includes("bilibili.com/video/")) {
                    const bvid = href.match(/\/video\/((?:av[\d]{1,10})|(?:BV[\w]{10}))/);
                    if (bvid && bvid[1]) {
                        const playerSrc = this.config.biliplayer === "h5"
                            ? `//www.bilibili.com/blackboard/html5mobileplayer.html?danmaku=0&poster=true&bvid=${bvid[1]}`
                            : `//player.bilibili.com/player.html?isOutside=true&autoplay=0&bvid=${bvid[1]}`;
                        return `<div class="relative w-full h-full" style="padding-bottom:55%; margin: 1rem 0;"><iframe class="absolute w-full h-full left-0 top-0" src="${playerSrc}" scrolling="no" border="0" frameborder="no" framespacing="0" allowfullscreen="true" style="border-radius:8px;"></iframe></div>`;
                    }
                }
            }

            if (href.includes("douban.com") && text.includes("|")) {
                let match = href.match(/https?:\/\/(movie|book|music)\.douban\.com\/subject\/(\d+)/) || href.match(/https?:\/\/(www\.)?douban\.com\/game\/(\d+)/);
                if (match) {
                    const parts = text.split("|");
                    return this.generateDoubanCard({
                        id: match[2], type: match[1] || "game", title: parts[0], rating: parts[1],
                        description: parts[2], cover: parts[3] || null, author: parts[4] || null, url: href
                    });
                }
            }
            return `<a class="primary" href="${href}" target="_blank">${text || href}</a>`;
        };

        marked.setOptions({ renderer: renderer, breaks: true, smartypants: false });

        // 3. 话题标签解析 (修复版：支持点号，仅在空格/换行处结束)
        marked.use({
            extensions: [{
                name: "hashtag",
                level: "inline",
                start: src => src.match(/#[^#\s]+/)?.index,
                tokenizer(src) {
                    // ^# 开头，匹配所有非空格和非井号字符（允许包含点、逗号等标点）
                    const rule = /^#([^#\s]+)/;
                    const match = rule.exec(src);
                    if (match) {
                        return {
                            type: "hashtag",
                            raw: match[0],
                            tag: match[1]
                        };
                    }
                },
                renderer: token => `<span class='tag-span'>#${token.tag}</span>`
            }]
        });
    }

    generateDoubanCard(t) {
        return `
            <div class="douban-card says-content w-full flex items-center border border-gray-200 dark:border-gray-600/50 my-4 p-2 relative shadow-lg rounded-lg">
                <div class="lg:flex lg:flex-col lg:mr-4 hidden">
                    <img class="cover-img douban-cover loaded" data-processed="true" src="${t.cover || `https://img1.doubanio.com/view/subject/s/public/${t.id}.jpg`}" alt="${t.title}">
                </div>
                <div class="flex flex-col flex-1 relative text-gray-700/90 dark:text-gray-500/90">
                    <div class="db-card-title"><a href="${t.url}" class="cute" target="_blank" rel="noreferrer">${t.title}</a>${t.author ? ` - ${t.author}` : ""}</div>
                    <div class="flex my-2">
                        <span class="rating-star allstar${Math.floor(t.rating)}"></span>
                        <span class="ml-1 rating-num">${t.rating}</span>
                    </div>
                    <div class="db-card-abstract text-sm">${t.description}</div>
                </div>
                <div class="absolute top-0 right-0 text-sm italic capitalize bg-orange-500 px-2 py-0.5 rounded-tr-lg rounded-bl-lg text-white">${t.type}</div>
            </div>`;
    }

    async loadMemos() {
        if (this.state.isLoading || !this.state.hasMore) return;
        this.state.isLoading = true;

        try {
            const url = `${this.config.memos}api/v1/memo?limit=${this.config.limit}&page=${this.state.currentPage}`;
            const response = await fetch(url);
            const ret = await response.json();
            const data = ret.data || [];

            if (data.length > 0) {
                await this.renderMemos(data);
                this.state.currentPage++;
            }

            if (data.length < this.config.limit || data.length === 0) {
                this.state.hasMore = false;
                if (this.loadButtonContainer) {
                    this.loadButton.textContent = "已经全部加载完了";
                    this.loadButton.disabled = true;
                }
            } else {
                this.loadButtonContainer.style.display = "block";
                this.loadButton.textContent = "点击加载更多";
            }
        } catch (error) {
            console.error("加载失败:", error);
            this.loadButton.textContent = "加载失败，点击重试";
        } finally {
            this.state.isLoading = false;
        }
    }

    async renderMemos(data) {
        let html = "";
        data.forEach((memo, index) => {
            let rawContent = memo.content;
            const mediaRegex = /(?<![\[\(\x21])(https?:\/\/(?:music\.163\.com|www\.bilibili\.com\/video)[^\s\)\x5d]*)(?![\]\)])/g;
            rawContent = rawContent.replace(mediaRegex, (url) => `[${url}](${url})`);

            const content = marked.parse(rawContent);
            const from = memo.from || "火星";
            const timestamp = this.formatTime(memo.updated_at);

            html += `
                <div class="says-card shadow-sm" data-aos="fade-up" style="animation-delay: ${index / 10}s;">
                    <div class="says-content">${content}</div>
                    <div class="flex justify-between items-center text-sm says-footer">
                        <div class="datatime flex-1" data-value="${memo.updated_at}">${timestamp}</div>
                        <div class="bb-tool sea-post-meta"><div class="from">---来自「${from}」</div></div>
                    </div>
                </div>`;
        });

        const loader = this.saysList.querySelector(".loader");
        if (loader) loader.remove();
        this.saysList.insertAdjacentHTML("beforeend", html);
        if (window.lazyLoadManager) window.lazyLoadManager.processImages("#says-list .says-content");
    }

    formatTime(t) {
        const e = Math.floor(Date.now() / 1000);
        const a = new Date(1000 * t);
        const i = [a.getHours().toString().padStart(2, "0"), a.getMinutes().toString().padStart(2, "0")].join(":");
        const s = e - t;
        if (s < 3600) return Math.floor(s / 60) + "分钟前";
        if (s < 86400) return Math.floor(s / 3600) + "小时前";
        if (s < 172800) return "昨天 " + i;
        if (s < 259200) return "前天 " + i;
        return [a.getFullYear(), (a.getMonth() + 1).toString().padStart(2, "0"), a.getDate().toString().padStart(2, "0")].join("/") + " <span class='time'>" + i + "</span>";
    }
}
